correctedCode:
#include <stdio.h>

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("Usage: %s <argument>\n", argv[0]);
        return 1;
    }
    printf("First argument: %s\n", argv[1]);
    return 0;
}
